#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
	int t;
	cin>>t;
	while(t--)
	{
	    int n;
	    cin>>n;
	    int N=3*n;
	    vector<long long> arr(N);
	    for(int i=0;i<N;i++)
	    {
	         cin>>arr[i];
	    }
	    sort(arr.rbegin(),arr.rend());
	    vector<long long > prefix(N+1,0);
	    for(int i=0;i<N;i++)
	    {
	        prefix[i+1]=prefix[i]+arr[i];
	    }
	    auto sum=[&](int l,int r)->long long {return prefix[r]-prefix[l];};
	    long long ans=0;
	    for(int i=0;i<=n;i++){
	        int Mb=n-i;
	        auto value = [&](int b)->long long { int p = i+2*b ;
	        int q= 3 * n - 2 * i - b;
	        long long result=0;
	        result+=6ll*sum(0,i);
	        result+=4ll*sum(i,p);
	        result+=3ll*sum(p,q);
	        return result;
	    };
	    int l=0;
	    int h=Mb;
	    while(l<h)
	    {
	        int mid=(l+h)/2;
	        int p=i+2* mid;
	        int q=3*n-2*i-mid;
	        long long del=arr[p]+arr[p+1]-3ll*arr[q-1];
	        if(del>=0)
	        l=mid+1;
	        else
	        h=mid;
	    }
	    ans=max(ans,value(l));
	    if(l>0)
	    ans=max(ans,value(l-1));
	    
	}
 cout<<ans<<endl;
}
}
